def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated full-width separator rows and the width of the framed area.
    separators = [r for r, row in enumerate(grid)
                  if row[0] != 0 and all(v == row[0] for v in row[:5])]
    frame_color = grid[0][0]
    frame_w = 0
    while frame_w < w and grid[0][frame_w] == frame_color:
        frame_w += 1

    # Find connected, non-background colored objects to the right of the frame.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(frame_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and frame_w <= nx < w
                            and grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            shape = tuple(tuple(1 if (y, x) in set(cells) else 0
                                for x in range(minc, maxc + 1))
                          for y in range(minr, maxr + 1))
            objects.append((shape, color))

    out = [row[:frame_w] for row in grid]
    for i in range(len(separators) - 1):
        top, bottom = separators[i] + 1, separators[i + 1]
        if top >= bottom:
            continue
        cells = [(r, c) for r in range(top, bottom)
                 for c in range(1, frame_w - 1) if grid[r][c] == 0]
        if not cells:
            continue
        minr, maxr = min(r for r, c in cells), max(r for r, c in cells)
        minc, maxc = min(c for r, c in cells), max(c for r, c in cells)
        mask = tuple(tuple(1 if (r, c) in set(cells) else 0
                           for c in range(minc, maxc + 1))
                     for r in range(minr, maxr + 1))
        for shape, color in objects:
            if shape == mask:
                for r, c in cells:
                    out[r][c] = color
                break
    return out
